SCHEMA = """
CREATE TABLE IF NOT EXISTS users(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, username TEXT UNIQUE NOT NULL, email TEXT NOT NULL, password TEXT NOT NULL, is_admin INTEGER DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS categories(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name TEXT UNIQUE NOT NULL, sort_order INTEGER DEFAULT 0, is_active INTEGER DEFAULT 1);
CREATE TABLE IF NOT EXISTS products(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, category_id BIGINT REFERENCES categories(id), name TEXT NOT NULL, description TEXT DEFAULT '', mrp DOUBLE PRECISION NOT NULL, price DOUBLE PRECISION NOT NULL, stock INTEGER NOT NULL DEFAULT 0, image TEXT DEFAULT '', is_active INTEGER DEFAULT 1, is_featured INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS shipping_methods(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name TEXT NOT NULL, charge DOUBLE PRECISION NOT NULL, days INTEGER NOT NULL, free_above DOUBLE PRECISION, is_active INTEGER DEFAULT 1);
CREATE TABLE IF NOT EXISTS orders(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT REFERENCES users(id), full_name TEXT, phone TEXT, address TEXT, city TEXT, pincode TEXT, shipping TEXT, shipping_charge DOUBLE PRECISION, subtotal DOUBLE PRECISION, total DOUBLE PRECISION, status TEXT DEFAULT 'Placed', courier TEXT DEFAULT '', tracking TEXT DEFAULT '', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, estimated_date TEXT DEFAULT '', estimated_time TEXT DEFAULT '');
CREATE TABLE IF NOT EXISTS order_items(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, order_id BIGINT REFERENCES orders(id), product_id BIGINT, name TEXT, price DOUBLE PRECISION, qty INTEGER);
"""

def connect():
    con = psycopg.connect(DATABASE_URL, row_factory=dict_row)
    return con

def init_db():
    with connect() as con:
        for statement in SCHEMA.strip().split(';'):
            if statement.strip():
                con.execute(statement)
        if not con.execute("SELECT 1 FROM users LIMIT 1").fetchone():
            admin_user = os.environ.get("ADMIN_USERNAME")
            admin_password = os.environ.get("ADMIN_PASSWORD")
            if admin_user and admin_password:
                con.execute("INSERT INTO users(username,email,password,is_admin) VALUES(%s,%s,%s,1)",
                    (admin_user, os.environ.get("ADMIN_EMAIL", "admin@vms.local"), generate_password_hash(admin_password)))
        if not con.execute("SELECT 1 FROM categories LIMIT 1").fetchone():
            with con.cursor() as cur:
                cur.executemany(
        "INSERT INTO categories(name,sort_order) VALUES(%s,%s)",
                [("Electronics", 1), ("Fashion", 2), ("Home & Kitchen", 3)])
            cats = {r['name']: r['id'] for r in con.execute("SELECT name,id FROM categories").fetchall()}
            with con.cursor() as cur:
                                  cur.executemany(
        "INSERT INTO products(category_id,name,description,mrp,price,stock,is_featured) VALUES(%s,%s,%s,%s,%s,%s,%s)",[
                (cats["Electronics"], "Wireless Earbuds", "Bluetooth 5.3, 24h battery.", 3999, 2999, 15, 1),
                (cats["Electronics"], "Smart Watch", "Fitness tracking and alerts.", 6499, 4999, 8, 0),
                (cats["Fashion"], "Cotton T-Shirt", "Soft everyday cotton.", 799, 399, 40, 1),
                (cats["Fashion"], "Denim Jacket", "Classic fit.", 2499, 1499, 0, 0),
                (cats["Home & Kitchen"], "Steel Water Bottle", "Leak-proof, 1 litre.", 899, 599, 25, 1),
                (cats["Home & Kitchen"], "Non-stick Pan", "24 cm, induction ready.", 1599, 1199, 12, 0)])
        if not con.execute("SELECT 1 FROM shipping_methods LIMIT 1").fetchone():
            with con.cursor() as cur:
                cur.executemany(
        "INSERT INTO shipping_methods(name,charge,days,free_above) VALUES(%s,%s,%s,%s)",
                [("Standard", 49, 5, 499), ("Express", 149, 2, None)])
        con.execute("ALTER TABLE orders ADD COLUMN IF NOT EXISTS estimated_date TEXT DEFAULT ''")
        con.execute("ALTER TABLE orders ADD COLUMN IF NOT EXISTS estimated_time TEXT DEFAULT ''")

def db():
    if "db" not in g:
        g.db = connect()
    return g.db

@app.teardown_appcontext
def close_db(_):
    d = g.pop("db", None)
    if d: d.close()

def q(sql, args=(), one=False):
    rows = db().execute(sql.replace('?', '%s'), args).fetchall()
    return (rows[0] if rows else None) if one else rows

def ex(sql, args=()):
    statement = sql.replace('?', '%s')
    if statement.lstrip().upper().startswith('INSERT INTO') and 'RETURNING' not in statement.upper():
        statement += ' RETURNING id'
        cur = db().execute(statement, args)
        new_id = cur.fetchone()['id']
        db().commit()
        return new_id
    cur = db().execute(statement, args)
    db().commit()
    return cur.rowcount

@app.template_filter("image_url")
def image_url(value):
    if not value: return ""
    if value.startswith("https://"): return value
    return url_for("static", filename="uploads/" + value)

def to_float(s):
    try: return float(s)
    except (TypeError, ValueError): return None

def to_int(s):
    try: return int(s)
    except (TypeError, ValueError): return None

def cart_lines():
    lines = []
    for pid, qty in session.get("cart", {}).items():
        p = q("SELECT * FROM products WHERE id=? AND is_active=1", (pid,), True)
        if p: lines.append({"p": p, "qty": qty, "total": p["price"] * qty})
    return lines

def restock(oid):
    for it in q("SELECT product_id, qty FROM order_items WHERE order_id=?", (oid,)):
        if it["product_id"]:
            ex("UPDATE products SET stock=stock+? WHERE id=?", (it["qty"], it["product_id"]))

@app.before_request
def load_user():
    uid = session.get("uid")
    g.user = q("SELECT * FROM users WHERE id=?", (uid,), True) if uid else None
    g.cart_count = sum(session.get("cart", {}).values())

def login_required(view):
    @wraps(view)
    def wrapper(*a, **k):
        if not g.user:
            flash("Please log in to continue.", "info")
            return redirect(url_for("login", next=request.path))
        return view(*a, **k)
    return wrapper

def admin_required(view):
    @wraps(view)
    def wrapper(*a, **k):
        if not g.user:
            return redirect(url_for("login", next=request.path))
        if not g.user["is_admin"]:
            abort(403)
        return view(*a, **k)
    return wrapper

