def alist(title, cols, rows, new=None):
    return render("alist", title=title, cols=cols, rows=rows, new_href=new)

@app.route("/admin")
@admin_required
def admin_dashboard():
    n = lambda sql: next(iter(q(sql, (), True).values()))
    stats = [("Products", n("SELECT COUNT(*) FROM products")),
             ("Active products", n("SELECT COUNT(*) FROM products WHERE is_active=1")),
             ("Categories", n("SELECT COUNT(*) FROM categories")),
             ("Orders", n("SELECT COUNT(*) FROM orders")),
             ("To process (Placed)", n("SELECT COUNT(*) FROM orders WHERE status='Placed'")),
             ("Revenue (excl. cancelled)", "\u20b9%.2f" % (n("SELECT COALESCE(SUM(total),0) FROM orders WHERE status!='Cancelled'") or 0))]
    low = q("SELECT name, stock FROM products WHERE stock<=5 AND is_active=1 ORDER BY stock LIMIT 10")
    return render("dash", stats=stats, low=low)

