@app.route("/admin/categories/<int:cid>/edit", methods=["GET", "POST"])
@admin_required
def cat_form(cid=None):
    row = q("SELECT * FROM categories WHERE id=?", (cid,), True) if cid else None
    if request.method == "POST":
        f = request.form
        name, order_no, active = f.get("name", "").strip(), to_int(f.get("sort_order")) or 0, 1 if "is_active" in f else 0
        if not name:
            flash("Name is required.", "error")
        else:
            try:
                if row: ex("UPDATE categories SET name=?, sort_order=?, is_active=? WHERE id=?", (name, order_no, active, cid))
                else: ex("INSERT INTO categories(name, sort_order, is_active) VALUES(?,?,?)", (name, order_no, active))
                flash("Category saved.", "success")
                return redirect(url_for("admin_categories"))
            except psycopg.errors.UniqueViolation:
                db().rollback()
                flash("A category with this name already exists.", "error")
    fields = [{"name": "name", "label": "Name", "type": "text", "value": pick(row, "name"), "required": True},
              {"name": "sort_order", "label": "Display order", "type": "number", "step": "1", "value": pick(row, "sort_order", 0)},
              {"name": "is_active", "label": "Active (visible in shop)", "type": "checkbox", "value": flag(row, "is_active")}]
    return render("aform", title="Edit category" if row else "New category", fields=fields, back=url_for("admin_categories"))

