@app.route("/admin/products/new", methods=["GET", "POST"])
@app.route("/admin/products/<int:pid>/edit", methods=["GET", "POST"])
@admin_required
def prod_form(pid=None):
    row = q("SELECT * FROM products WHERE id=?", (pid,), True) if pid else None
    cats = q("SELECT id, name FROM categories ORDER BY name")
    if request.method == "POST":
        f = request.form
        name, cid = f.get("name", "").strip(), to_int(f.get("category_id"))
        price, mrp, stock = to_float(f.get("price")), to_float(f.get("mrp")), to_int(f.get("stock"))
        img = row["image"] if row else ""
        err = None
        if not cid: err = "Create a category first."
        elif not name: err = "Name is required."
        elif price is None or mrp is None or price < 0 or price > mrp: err = "Selling price must be 0 or more and not above MRP."
        elif stock is None or stock < 0: err = "Stock must be a whole number, 0 or more."
        upload = request.files.get("image")
        if not err and upload and upload.filename:
            ext = upload.filename.rsplit(".", 1)[-1].lower() if "." in upload.filename else ""
            if ext not in ALLOWED: err = "Image must be PNG, JPG, WEBP or GIF."
            else:
                try:
                    if not os.environ.get("CLOUDINARY_URL"):
                        raise RuntimeError("CLOUDINARY_URL is not configured")
                    result = cloudinary.uploader.upload(upload, folder="vms-store/products", resource_type="image")
                    img = result["secure_url"]
                except Exception:
                    app.logger.exception("Cloudinary upload failed")
                    err = "Image upload failed. Check Cloudinary configuration."
        if err:
            flash(err, "error")
        else:
            vals = (cid, name, f.get("description", ""), mrp, price, stock, img, 1 if "is_active" in f else 0, 1 if "is_featured" in f else 0)
            if row: ex("""UPDATE products SET category_id=?, name=?, description=?, mrp=?, price=?, stock=?, image=?, is_active=?, is_featured=? WHERE id=?""", vals + (pid,))
            else: ex("""INSERT INTO products(category_id,name,description,mrp,price,stock,image,is_active,is_featured) VALUES(?,?,?,?,?,?,?,?,?)""", vals)
            flash("Product saved.", "success")
            return redirect(url_for("admin_products"))
    fields = [{"name": "name", "label": "Name", "type": "text", "value": pick(row, "name"), "required": True},
              {"name": "category_id", "label": "Category", "type": "select", "value": pick(row, "category_id"), "options": [(c["id"], c["name"]) for c in cats]},
              {"name": "price", "label": "Selling price (\u20b9)", "type": "number", "step": "0.01", "value": pick(row, "price"), "required": True},
              {"name": "mrp", "label": "MRP (\u20b9)", "type": "number", "step": "0.01", "value": pick(row, "mrp"), "required": True},
              {"name": "stock", "label": "Stock", "type": "number", "step": "1", "value": pick(row, "stock", 0), "required": True},
              {"name": "description", "label": "Description", "type": "textarea", "value": pick(row, "description")},
              {"name": "image", "label": "Image (PNG/JPG/WEBP/GIF)", "type": "file", "image": row["image"] if row else ""},
              {"name": "is_active", "label": "Active (visible in shop)", "type": "checkbox", "value": flag(row, "is_active")},
              {"name": "is_featured", "label": "Featured on home page", "type": "checkbox", "value": flag(row, "is_featured", False)}]
    return render("aform", title="Edit product" if row else "New product", fields=fields, back=url_for("admin_products"))

