@app.route("/admin/orders/<int:oid>", methods=["GET", "POST"])
@admin_required
def admin_order(oid):
    o = q("SELECT * FROM orders WHERE id=?", (oid,), True)
    if not o: abort(404)
    if request.method == "POST":
        f, new = request.form, request.form.get("status")
        if o["status"] == "Cancelled":
            flash("Cancelled orders cannot be changed.", "error")
        elif new not in STATUSES:
            flash("Invalid status.", "error")
        else:
            if new == "Cancelled":
                restock(oid)

            estimated_date = f.get("estimated_date", "").strip()
            estimated_time = f.get("estimated_time", "").strip()

            ex("""
                UPDATE orders
                SET status=?,
                    courier=?,
                    tracking=?,
                    estimated_date=?,
                    estimated_time=?,
                    updated_at=CURRENT_TIMESTAMP
                WHERE id=?
            """, (
                new,
                f.get("courier", "").strip(),
                f.get("tracking", "").strip(),
                estimated_date,
                estimated_time,
                oid
            ))

            flash("Order updated.", "success")
        return redirect(url_for("admin_order", oid=oid))
    return render("order", o=o, lines=q("SELECT * FROM order_items WHERE order_id=?", (oid,)), statuses=STATUSES, admin=True)

